from sqlalchemy.orm import Session
from fraud_service.app.models.fraud import FraudCheck
from fraud_service.app.schemas.fraud import FraudCheckRequest, RuleResult
from fraud_service.app.rules.velocity import VelocityRules
from fraud_service.app.rules.blocklist import BlocklistRules
from fraud_service.app.rules.card_rules import CardRules
from fraud_service.app.rules.amount_rules import AmountRules


class FraudRulesEngine:

    def __init__(self):
        self.velocity = VelocityRules()
        self.blocklist = BlocklistRules()
        self.card_rules = CardRules()
        self.amount_rules = AmountRules()

    async def evaluate(self, request: FraudCheckRequest, db: Session) -> tuple[list[RuleResult], int]:
        results: list[RuleResult] = []
        total_score = 0

        def add(rule: RuleResult):
            results.append(rule)
            nonlocal total_score
            total_score += rule.score_impact

        # ── BLOCKLIST (Instant block) ──────────────────────────────────
        add(self.blocklist.check_card(db, request.card.fingerprint))
        add(self.blocklist.check_ip(db, request.customer.ip_address))
        add(self.blocklist.check_email(db, request.customer.email))
        add(self.blocklist.check_customer(db, request.customer.id))

        # ── CARD RULES ──────────────────────────────────────────────────
        add(self.card_rules.check_expiry(request.card.exp_month, request.card.exp_year))

        is_first_use = (
            db.query(FraudCheck)
            .filter(FraudCheck.card_fingerprint == request.card.fingerprint)
            .count()
        ) == 0
        add(self.card_rules.check_card_testing_pattern(request.amount, is_first_use))

        # ── VELOCITY RULES ──────────────────────────────────────────────
        add(self.velocity.check_card_velocity(db, request.card.fingerprint))
        add(self.velocity.check_ip_velocity(db, request.customer.ip_address))
        add(self.velocity.check_customer_velocity(db, request.customer.id))

        # ── AMOUNT RULES ────────────────────────────────────────────────
        add(self.amount_rules.check_micro_transaction(request.amount))
        add(self.amount_rules.check_round_number(request.amount))
        add(self.amount_rules.check_email_domain(request.customer.email))

        customer_tx_count = (
            db.query(FraudCheck)
            .filter(FraudCheck.customer_id == request.customer.id)
            .count()
        )
        add(self.amount_rules.check_high_amount_new_customer(request.amount, customer_tx_count))

        return results, min(total_score, 100)
